import { useNavigate,useNavigation,useActionData ,redirect} from 'react-router-dom';

import classes from './EventForm.module.css';
import {Form} from 'react-router-dom'
function EventForm({ method, event }) {
    const data = useActionData();
  const navigate = useNavigate();
  const navigation = useNavigation();
  const isSubmitting = navigation.state === 'submitting';
  function cancelHandler() {
    navigate('..');
  }

  return (
    <Form method={method} className={classes.form}>
        {data && data.errors && <ul>{Object.values(data.errors).map(err => <li key={err}>{err}</li>)}</ul>}
      <p>
        <label htmlFor="title">Title</label>
        <input id="title" type="text" name="title" required defaultValue={event.title} />
      </p>
      <p>
        <label htmlFor="image">Image</label>
        <input id="image" type="url" name="image" required defaultValue={event.image} />
      </p>
      <p>
        <label htmlFor="date">Date</label>
        <input id="date" type="date" name="date" required defaultValue={event.date} />
      </p>
      <p>
        <label htmlFor="description">Description</label>
        <textarea id="description" name="description" rows="5" required defaultValue={event.description} />
      </p>
      <div className={classes.actions}>
        <button type="button" onClick={cancelHandler} disabled={isSubmitting}>
          Cancel
        </button>
        <button disabled={isSubmitting}>{isSubmitting ? 'Submitting...' : 'Save'}</button>
      </div>
    </Form>
  );
}

export default EventForm;

export async function action({request,params}){
    const formData = await request.formData();
    const method = request.method;
    const formEntries = {
        title : formData.get('title'),
        date : formData.get('date'),
        description : formData.get('description'),
        image : formData.get('image')
    }
    let url = 'http://localhost:8080/events';
    if(method === 'PATCH'){
        url += params.id
    }
    const response = await fetch(url,{
        method : method,
        headers : {
            'Content-Type' : 'application/json'
        },
        body : JSON.stringify(formEntries),
    })
    if(response.status === 422) {
        return response
    }
    if(!response.ok){
        throw new response({message : 'could not do it!'},{status : 500})
    }
    return redirect('/events')

}
